"""California: the bar and the Weather view on the engine jobs' interfaces as built (CA/engine/BAR_NEEDS.md)."""
import sys, os
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from lib import F
f = F()
# the engine's steps carry their id as k (SE.STORM, SE.WIND, SE.SKY) and its word on the weather is info(): key, wind.key, sky.key
f.rep("const stepId = (s, list) => (s && typeof s === 'object' && list.some(x => x.id === s.id) ? s.id : typeof s === 'string' && list.some(x => x.id === s) ? s : null);",
      "const stepKey = s => (s && typeof s === 'object' ? s.id || s.k || s.key || null : typeof s === 'string' ? s : null);\n  const stepId = (s, list) => { const k = stepKey(s); return k && list.some(x => x.id === k) ? k : null; };")
f.rep("cs = ctx.sky && typeof ctx.sky === 'object' ? ctx.sky.id : ctx.sky, sky = (typeof cs === 'string' && WX_SKY.some(x => x[0] === cs) ? cs : WXNOW.sky) || 'none', ew = ctx.wx && typeof ctx.wx === 'object' ? ctx.wx : {};",
      "ew = ctx.wx && typeof ctx.wx === 'object' ? ctx.wx : {}, cs = ew.sky && typeof ew.sky === 'object' && ew.sky.key ? (ew.sky.on === false ? 'none' : ew.sky.key) : stepKey(ctx.sky), sky = (typeof cs === 'string' && WX_SKY.some(x => x[0] === cs) ? cs : WXNOW.sky) || 'none';")
f.rep("    return { rain: r, wind: w, sky, gust: Math.max(rg, wg), rainGust: rg, windGust: wg, snowM, elev: isN(ew.elevationM) ? +ew.elevationM : isN(ctx.elev) ? +ctx.elev : WXNOW.elev };",
      "    const rg2 = isN(ew.gust) && stepKey(ew) === r.id ? +ew.gust : rg, wg2 = ew.wind && isN(ew.wind.gust) && ew.wind.key === w.id ? +ew.wind.gust : wg;\n    return { rain: r, wind: w, sky, gust: isN(ew.gustMph) ? Math.max(+ew.gustMph, 0) : Math.max(rg2, wg2), rainGust: rg2, windGust: wg2, snowM, elev: isN(ew.elevationM) ? +ew.elevationM : isN(ctx.elev) ? +ctx.elev : WXNOW.elev, engSnow: typeof ew.snowing === 'boolean' ? ew.snowing : null, local: ew.wind && ew.wind.local ? String(ew.wind.local) : '' };")
f.rep("snowing = wx.rain.id !== 'dry' && el != null && wx.snowM > 0 && el >= wx.snowM, add = snowing ? wx.rain.swe * 5.2 : 0;", "snowing = wx.rain.id !== 'dry' && (wx.engSnow != null ? wx.engSnow : el != null && wx.snowM > 0 && el >= wx.snowM), add = snowing ? wx.rain.swe * 5.2 : 0;")
f.rep("`<br>Snow: this storm adds about <b>${D(s.add, 0)} lb a square foot</b>${s.pg > 0 ? `, ${pct(clamp(s.add / s.pg, 0, 9.99))} of the ${N(Math.round(s.pg))} lb ground snow load here (ASCE 7-22 as its map service gives it)` : '; the ground snow load here is not in the page\\'s data'}, at about ${N(Math.round(s.el * 3.281 / 10) * 10)} ft.",
      "`<br>Snow: this storm adds about <b>${D(s.add, 0)} lb a square foot</b>${s.pg > 0 ? `, ${pct(clamp(s.add / s.pg, 0, 9.99))} of the ${N(Math.round(s.pg))} lb ground snow load here (ASCE 7-22 as its map service gives it)` : '; the ground snow load here is not in the page\\'s data'}${s.el != null ? `, at about ${N(Math.round(s.el * 3.281 / 10) * 10)} ft` : ''}.")
# the bar
f.rep("      const idAt = (list, v) => (typeof v === 'string' ? (list.find(x => x.id === v) || {}).id : isN(v) && list[v] ? list[v].id : v && typeof v === 'object' && v.id ? (list.find(x => x.id === v.id) || {}).id : null) || null;",
      "      const idAt = (list, v) => (typeof v === 'string' ? (list.find(x => x.id === v) || {}).id : isN(v) && list[v] ? list[v].id : v && typeof v === 'object' ? (list.find(x => x.id === stepKey(v)) || {}).id : null) || null;\n      /* the engine's own account of its weather (its stormKit's info), where it gives one */\n      const wxInfo = () => { try { return en && typeof en.weather === 'function' ? en.weather() : en && en.stormKit && typeof en.stormKit.info === 'function' && enHas().wx ? en.stormKit.info() : null; } catch (e) { return null; } };\n      /* the aircraft, ships and bridges kit: en.air (en.sky where an engine carries it under that name as an object) */\n      const airKit = () => (en && en.air && typeof en.air.info === 'function' ? en.air : en && en.sky && typeof en.sky === 'object' && typeof en.sky.info === 'function' ? en.sky : null);\n      function airLine() { const K = airKit(), g = en ? en.graphics() : null; if (!K || !g || g.air === false) return ''; let i = null; try { i = K.info(); } catch (e) { i = null; } if (!i || !i.name) return '';\n        return `Nearest airport: <b>${esc(i.name)}</b>${i.airport ? ' (' + esc(i.airport) + ')' : ''}${isN(i.km) ? ', ' + D(+i.km, 0) + ' km' : ''}${i.landing && i.landing.length ? ` · landing on ${esc(i.landing.join(', '))}` : ''}${i.departing && i.departing.length ? `, departing ${esc(i.departing.join(', '))}` : ''}${i.arrivalsPerHour || i.departuresPerHour ? ` · ${D(+i.arrivalsPerHour || 0, 0)} arrivals and ${D(+i.departuresPerHour || 0, 0)} departures an hour at this hour` : ''}${isN(i.arriving) ? ` · ${N((+i.arriving || 0) + (+i.departingNow || 0))} flights drawn` : ''}.${i.what && i.what.generated ? ' Generated, not observed: ' + esc(i.what.generated) + '.' : i.generated ? ' Generated, not observed: ' + esc(i.generated) + '.' : ''}${i.real && typeof i.real === 'string' && !/^runway ends/.test(i.real) ? ' ' + esc(i.real.charAt(0).toUpperCase() + i.real.slice(1)) + '.' : ''}`; }")
f.rep("        if (H.wx) { WXNOW.rain = idAt(WX_RAIN, st.stormKey) || idAt(WX_RAIN, g.storm) || WXNOW.rain; WXNOW.wind = idAt(WX_WIND, st.windKey) || idAt(WX_WIND, g.wind) || WXNOW.wind; WXNOW.sky = idAt(SKY_IDS, g.skyState) || idAt(SKY_IDS, st.sky) || WXNOW.sky; }",
      "        if (H.wx) { const I = wxInfo() || {}; WXNOW.rain = idAt(WX_RAIN, I.key) || idAt(WX_RAIN, st.stormKey) || idAt(WX_RAIN, g.storm) || WXNOW.rain; WXNOW.wind = idAt(WX_WIND, I.wind) || idAt(WX_WIND, st.windKey) || idAt(WX_WIND, g.wind) || WXNOW.wind; WXNOW.sky = idAt(SKY_IDS, I.sky) || idAt(SKY_IDS, g.skyState) || idAt(SKY_IDS, st.sky) || WXNOW.sky; }")
f.rep("if (st && typeof st.altaCanFly === 'boolean') return st.altaCanFly;", "const I = wxInfo(); if (I && typeof I.fly === 'boolean') return I.fly; if (st && typeof st.altaCanFly === 'boolean') return st.altaCanFly;")
f.rep("      const NOFLY = \"Don't waste a $40,000 drone, stupid. Use the UAPs.\";", "      const NOFLY = \"Don't waste a $40,000 drone, stupid. Use the UAPs.\";   /* the engine shows the same words over the view (en.NOFLY) */")
f.rep("        const wx = wxResolve({}), st = en ? en.state() || {} : {}, H = enHas(), bits = [`<b>${esc(wxTitle(wx))}</b>`];",
      "        const I = wxInfo(), wx = wxResolve(I ? { wx: I } : {}), st = en ? en.state() || {} : {}, H = enHas(), bits = [`<b>${esc(wxTitle(wx))}</b>`];\n        /* the engine's own sentence, and its notes on what in the picture is a choice */\n        if (I && I.text && !(wx.rain.id === 'dry' && wx.wind.id === 'calm' && wx.sky === 'none')) { const notes = [I.note, I.wind && I.wind.level ? I.wind.note : '', I.sky && I.sky.level ? I.sky.note : '', I.sky && I.sky.held ? 'The sky chosen is held off: ' + I.sky.held : ''].filter(x => x && typeof x === 'string');\n          return `<b>${esc(wxTitle(wx))}</b> · ${esc(I.text)}${WXNOW.elev != null ? ` The ground here is ${N(Math.round(WXNOW.elev * 3.281 / 10) * 10)} ft above the sea.` : ''}${notes.length ? ` <span class=\"mini\">${esc(notes.join(' '))}</span>` : ''}`; }")
f.rep("bits.push(`${st.precip === 'snow' ? 'snow' : 'rain'} drawn at ${D(+st.rainMmH, +st.rainMmH < 10 ? 1 : 0)} mm an hour`);", "bits.push(`${typeof st.precip === 'string' && st.precip !== 'none' ? st.precip : 'rain'} drawn at ${D(+st.rainMmH, +st.rainMmH < 10 ? 1 : 0)} mm an hour`);")
f.rep("air = st.air && typeof st.air === 'object' ? st.air : null;", "air = st.air && typeof st.air === 'object' && st.air.on !== false ? st.air : null, airN = air ? (+air.flights || +air.n || 0) : 0;")
f.rep("${air && isN(air.n) && air.n > 0 ? ` · ${plural(+air.n, 'aircraft')} in the sky${air.airport ? ' near ' + esc(air.airport) : ''}` : ''}", "${airN > 0 ? ` · ${plural(airN, 'flight')} in the sky` : ''}")
f.rep("title=\"Airliners on the approaches to the airports, and the aircraft over the bay\">${gNow && gNow.air ? 'Air traffic on' : 'Air traffic off'}</button>` : ''}",
      "title=\"Airliners on the real approaches to the airports, the Navy in San Diego Bay and the landmark bridges\">${gNow && gNow.air ? 'Aircraft, ships and bridges: on' : 'Aircraft, ships and bridges: off'}</button>` : ''}")
f.rep("            <output id=\"scEnStormO\">${wxLine()}</output>", "            <output id=\"scEnStormO\">${wxLine()}</output>${H.air && airLine() ? `<span class=\"mini sc-airline\" id=\"scEnAirO\">${airLine()}</span>` : ''}")
f.rep(".sc-wxrow output{flex:1 1 100%", ".sc-wxrow output{flex:1 1 100%", 0)
f.save()
